import { fireEvent, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../../types";
import { BotTurnEndedEvent } from "./BotTurnEndedEvent";

const baseEvent: ConversationEvent = {
  __typename: "ConversationEvent",
  id: "1",
  conversationEventType: ConversationEventType.BotTurnEnded,
  name: "bot_turn_ended",
  actionText: "",
  flowId: "",
  slotValue: null,
  stepId: "",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  metadata: {
    parseData: {},
  },
};

describe("BotTurnEndedEvent", () => {
  it("renders 'Bot turn ended' label", () => {
    renderWithProviders(<BotTurnEndedEvent event={baseEvent} isSelected={false} />);

    expect(screen.getByText("Agent turn ended")).toBeInTheDocument();
  });

  it("renders as a button", () => {
    renderWithProviders(<BotTurnEndedEvent event={baseEvent} isSelected={false} />);

    expect(screen.getByRole("button")).toBeInTheDocument();
  });

  describe("hover actions", () => {
    const actions = [{ icon: {} as never, label: "Copy", action: vi.fn() }];

    it("does not show action button when not hovered", () => {
      renderWithProviders(
        <BotTurnEndedEvent
          event={baseEvent}
          isSelected={false}
          conversationEventActions={actions}
        />,
      );

      expect(screen.queryByText("Copy")).not.toBeInTheDocument();
    });

    it("shows action button on hover", () => {
      renderWithProviders(
        <BotTurnEndedEvent
          event={baseEvent}
          isSelected={false}
          conversationEventActions={actions}
        />,
      );

      fireEvent.mouseEnter(screen.getByRole("button"));
      expect(screen.getByText("Copy")).toBeInTheDocument();
    });

    it("hides action button after mouse leaves", () => {
      renderWithProviders(
        <BotTurnEndedEvent
          event={baseEvent}
          isSelected={false}
          conversationEventActions={actions}
        />,
      );

      const container = screen.getByRole("button");
      fireEvent.mouseEnter(container);
      fireEvent.mouseLeave(container);
      expect(screen.queryByText("Copy")).not.toBeInTheDocument();
    });
  });
});
